	private BufferedImage loadAndResize(int spriteId) {
		BufferedImage image = spriteManager.getSprite(spriteId, 0);
		if (image == null) {
			return null;
		}

		return ImageUtil.resizeCanvas(image, 15, ICON_DIMENSIONS.height);
	}

	private boolean inLms() {
